using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";
var topic = args.Length > 0 ? string.Join(' ', args) : "recent advances in quantum computing";

Console.WriteLine($"🔍 Research Agent — investigating: \"{topic}\"\n");

// --- Build the AI client with tools ---
var notepad = new Notepad();
IChatClient client = new OpenAIClient(openAiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(WebSearch.SearchAsync),
        AIFunctionFactory.Create(notepad.AddNote),
        AIFunctionFactory.Create(notepad.GetNotes),
    ]
};

// --- Agent loop ---
List<ChatMessage> messages =
[
    new(ChatRole.System, """
        You are a research agent. Your goal is to research a topic thoroughly.
        1. Use the web_search tool multiple times with different queries to gather information.
        2. Use the add_note tool to save key findings as you go.
        3. After gathering enough information, use get_notes to review your notes.
        4. Finally, provide a well-structured summary of your findings to the user.
        Be thorough — perform at least 3 searches before summarizing.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
];

var response = await client.GetResponseAsync(messages, chatOptions);
Console.WriteLine("\n═══════════════════════════════════════");
Console.WriteLine("📋 RESEARCH SUMMARY");
Console.WriteLine("═══════════════════════════════════════\n");
Console.WriteLine(response.Text);
Console.WriteLine("\n═══════════════════════════════════════");
Console.WriteLine($"📝 Notes collected: {notepad.Count}");
Console.WriteLine("═══════════════════════════════════════");

// --- Tools ---

/// <summary>Simulated web search tool.</summary>
static class WebSearch
{
    [Description("Search the web for information on a query. Returns a list of result snippets.")]
    public static async Task<string> SearchAsync(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        // Simulate network latency
        await Task.Delay(250);

        // In production, replace with a real search API (Bing, Google, Tavily, etc.)
        return $"""
            Search results for "{query}":
            1. [Research Article] Recent studies show significant progress in {query}. Key researchers have published findings demonstrating breakthroughs in efficiency and scalability.
            2. [News] A leading tech company announced new developments in {query}, with applications expected within the next 2-3 years.
            3. [Academic Paper] A comprehensive review of {query} was published, highlighting both current capabilities and remaining challenges in the field.
            4. [Industry Report] Market analysis suggests the {query} sector will grow substantially, driven by increased investment and government funding.
            """;
    }
}

/// <summary>Note-taking tool for the agent to persist findings.</summary>
class Notepad
{
    private readonly List<string> _notes = [];

    public int Count => _notes.Count;

    [Description("Save a research note. Use this to record important findings.")]
    public string AddNote([Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return "Your research notes:\n" +
            string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

